def get_string(key: str, language: str = "en") -> str:
    """Get translated string with fallback"""
    if language in STRINGS and key in STRINGS[language]:
        return STRINGS[language][key]
    if key in STRINGS["en"]:
        return STRINGS["en"][key]
    return key
